23	std::uint64_t LlmClient::submit(std::string systemPrompt,
24	                                std::vector<ChatTurn> history,
25	                                std::string userMessage) {
26	    ChatRequest req;
27	    req.id = nextId_.fetch_add(1);
28	    req.systemPrompt = std::move(systemPrompt);
29	    req.history = std::move(history);
30	    req.userMessage = std::move(userMessage);
31	
32	    {
33	        std::lock_guard<std::mutex> lock(requestMutex_);
34	        requests_.push(std::move(req));
35	    }
36	    requestCv_.notify_one();
37	    return req.id;
38	}
