70	std::string DialogUI::handleEvent(const sf::Event& event) {
71	    if (!inputEnabled_) return {};
72	
73	    if (event.type == sf::Event::TextEntered) {
74	        const auto unicode = event.text.unicode;
75	        if (unicode == 8) {  // backspace
76	            if (!input_.empty()) input_.pop_back();
77	        } else if (unicode == 13 || unicode == 10) {  // enter
78	            // Handled in KeyPressed below to avoid double-fire on some platforms.
79	        } else if (unicode >= 32 && unicode < 127) {
80	            input_ += static_cast<char>(unicode);
81	        }
82	        return {};
83	    }
84	
85	    if (event.type == sf::Event::KeyPressed &&
86	        (event.key.code == sf::Keyboard::Enter || event.key.code == sf::Keyboard::Return)) {
87	        if (input_.empty()) return {};
88	        std::string submitted = std::move(input_);
89	        input_.clear();
90	        return submitted;
91	    }
92	    return {};
93	}
