70	ChatReply LlmClient::processOne(const ChatRequest& req) {
71	    ChatReply reply;
72	    reply.id = req.id;
73	
74	    // Build Ollama /api/chat body. Ollama is OpenAI-style: messages[] with
75	    // role/content, optional options for temperature, stream=false for a
76	    // single non-streamed response.
77	    json messages = json::array();
78	    if (!req.systemPrompt.empty()) {
79	        messages.push_back({{"role", "system"}, {"content", req.systemPrompt}});
80	    }
81	    for (const auto& turn : req.history) {
82	        messages.push_back({{"role", turn.role}, {"content", turn.content}});
83	    }
84	    messages.push_back({{"role", "user"}, {"content", req.userMessage}});
85	
86	    json body = {
87	        {"model", config_.model},
88	        {"messages", messages},
89	        {"stream", false},
90	        {"options", {{"temperature", config_.temperature}}},
91	    };
92	    std::string bodyStr = body.dump();
93	
94	    httplib::Client cli(config_.host, config_.port);
95	    cli.set_read_timeout(config_.requestTimeoutSeconds, 0);
96	    cli.set_write_timeout(config_.requestTimeoutSeconds, 0);
97	    cli.set_connection_timeout(5, 0);
98	
99	    auto res = cli.Post("/api/chat", bodyStr, "application/json");
100	    if (!res) {
101	        reply.errorMessage = "could not reach Ollama at " + config_.host + ":" +
102	                             std::to_string(config_.port);
103	        return reply;
104	    }
105	    if (res->status != 200) {
106	        reply.errorMessage = "Ollama returned HTTP " + std::to_string(res->status) +
107	                             ": " + res->body;
108	        return reply;
109	    }
110	
111	    try {
112	        json parsed = json::parse(res->body);
113	        // Ollama replies with { "message": { "role": ..., "content": ... }, ... }
114	        if (parsed.contains("message") && parsed["message"].contains("content")) {
115	            reply.content = parsed["message"]["content"].get<std::string>();
116	            reply.ok = true;
117	        } else if (parsed.contains("error")) {
118	            reply.errorMessage = parsed["error"].get<std::string>();
119	        } else {
120	            reply.errorMessage = "unexpected response shape from Ollama";
121	        }
122	    } catch (const std::exception& e) {
123	        reply.errorMessage = std::string("failed to parse Ollama reply: ") + e.what();
124	    }
125	    return reply;
126	}
